# Generated by tools/render_controls.py — edit the data files, not this file.
#
# Rule:        CKV_AWS_8 (checkov 3.3.16)
# Applies to:  aws_instance, aws_launch_configuration
# Answered by: aws_compute_assets#unencrypted_volumes
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_8'] || []
applies_to   = %w[aws_instance aws_launch_configuration]

control 'CKV_AWS_8' do
  title 'Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the instances and launch configurations that actually exist.

    Checkov reads the block devices declared in HCL. This reads
    DescribeVolumes, so a volume attached later, by hand, outside Terraform
    is assessed too -- and that is the volume most likely to be unencrypted.
  DESC

  desc 'rationale', <<~RATIONALE
    An unencrypted volume exposes its data to anyone who can reach the
    underlying snapshot or the storage service, without needing access to
    the instance.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: every declared block device sets encrypted = true
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_instance:

      resource "aws_instance" "app" {
        ami           = var.ami_id
        instance_type = "t3.micro"

        root_block_device {
          encrypted  = true
          kms_key_id = aws_kms_key.ebs.arn   # omit for the AWS-managed key
        }

        ebs_block_device {
          device_name = "/dev/sdb"
          encrypted   = true
        }
      }

    Out of band — aws_instance:

      aws ec2 create-snapshot --volume-id <vol>
      aws ec2 copy-snapshot --source-snapshot-id <snap> --encrypted \
        --source-region <region>
      aws ec2 create-volume --snapshot-id <encrypted-snap> \
        --availability-zone <az>
      # then detach the old volume and attach the new one

    Note (aws_instance): An attached volume cannot be encrypted in place; both
    paths replace the volume. Setting `encrypted = true` in Terraform on an
    existing instance forces replacement -- plan before applying.

    Terraform — aws_launch_configuration:

      resource "aws_launch_configuration" "app" {
        name_prefix   = "app-"
        image_id      = var.ami_id
        instance_type = "t3.micro"

        root_block_device {
          encrypted = true
        }
      }

    Note (aws_launch_configuration): Immutable: the fix replaces the launch
    configuration and the instances the ASG launches from it.
  FIX

  tag checkov_id:       'CKV_AWS_8'
  tag checkov_category: 'ENCRYPTION'
  tag checkov_version:  '3.3.16'
  tag checkov_kind:     'custom'
  tag tf_resources:     %w[aws_instance aws_launch_configuration]
  tag tf_argument:      '(custom check logic)'
  tag tf_docs:          'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/instance'
  tag nist:             ['SC-28', 'SC-28 (1)']
  tag nist_r4:          ['SC-28', 'SC-28 (1)']
  tag cci:              ['CCI-001199', 'CCI-002475']
  tag ksi:              ['KSI-SVC-CER']
  tag severity:         'high'
  tag severity_source:  'assessed'
  tag nist_source:      'reviewed'
  tag implementation_status: 'implemented'

  assets = aws_compute_assets(regions: scan_regions)

  # A region that could not be READ is not a region with nothing in it. A denied
  # DescribeInstances, a throttled call or an unreachable endpoint is recorded in
  # unreadable_regions and contributes no rows, so without this the assets that
  # region holds are simply absent from the assessment — a PASS over the regions
  # that answered, or a Not Applicable if none did.
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe "aws_instance enumeration" do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # Only the asset types this check declares, only what the boundary has, and
  # only those that express the setting at all — a launch template has no
  # ebs_optimized, and nil must not read as a passing false.
  # A nil field is the FAILING state for a presence check, so it is
  # deliberately not filtered out here.
  in_scope = assets.assets_of(applies_to, exempt: exempt)

  # `|| !unreadable.empty?` keeps the control applicable when the read failed, so
  # the assertion above is reachable: only_if suppresses every describe in the
  # control, the one reporting the failure included.
  applicable = !in_scope.empty? || !unreadable.empty?

  # Two statements, not a ternary: InSpec's AST impact collector calls `.value`
  # on the argument node, and a ternary is an IfNode with none — it aborts
  # `check` for the whole profile before a single control runs.
  impact 0.7
  impact 0.0 unless applicable

  only_if("no #{applies_to.join(', ')} in scope expressing this setting") { applicable }

  in_scope.each do |asset|
    describe "#{asset[:type]} #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:unencrypted_volumes] }
      it { should satisfy('be unset or empty') { |v| v.nil? || (v.respond_to?(:empty?) && v.empty?) } }
    end
  end
end
